import{_ as i,o as e,c as n,a2 as o}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Planificación Académica: Proyecto Sociotecnológico III (Trimestre IX)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_III/Planificacion_Trimestre_III-IX.md","filePath":"materias/Proyecto_Sociotecnologico_III/Planificacion_Trimestre_III-IX.md"}'),r={name:"materias/Proyecto_Sociotecnologico_III/Planificacion_Trimestre_III-IX.md"};function c(l,a,t,s,d,u){return e(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="planificacion-academica-proyecto-sociotecnologico-iii-trimestre-ix" tabindex="-1">Planificación Académica: Proyecto Sociotecnológico III (Trimestre IX) <a class="header-anchor" href="#planificacion-academica-proyecto-sociotecnologico-iii-trimestre-ix" aria-label="Permalink to &quot;Planificación Académica: Proyecto Sociotecnológico III (Trimestre IX)&quot;">​</a></h1><p>El Trimestre IX representa la etapa de consolidación, aseguramiento de la calidad, implantación real y defensa final del Proyecto Sociotecnológico III, culminando el primer ciclo de formación de la Licenciatura / Ingeniería en Informática.</p><hr><h2 id="📅-trimestre-ix-pruebas-optimizacion-implantacion-y-socializacion-final-unidades-5-6-y-7" tabindex="-1">📅 Trimestre IX: Pruebas, Optimización, Implantación y Socialización Final (Unidades 5, 6 y 7) <a class="header-anchor" href="#📅-trimestre-ix-pruebas-optimizacion-implantacion-y-socializacion-final-unidades-5-6-y-7" aria-label="Permalink to &quot;📅 Trimestre IX: Pruebas, Optimización, Implantación y Socialización Final (Unidades 5, 6 y 7)&quot;">​</a></h2><h3 id="📝-evaluacion-1-planificacion-y-aplicacion-de-pruebas-de-software-unidad-6" tabindex="-1">📝 Evaluación 1: Planificación y Aplicación de Pruebas de Software (Unidad 6) <a class="header-anchor" href="#📝-evaluacion-1-planificacion-y-aplicacion-de-pruebas-de-software-unidad-6" aria-label="Permalink to &quot;📝 Evaluación 1: Planificación y Aplicación de Pruebas de Software (Unidad 6)&quot;">​</a></h3><p><strong>Objetivo:</strong> Garantizar la calidad, confiabilidad y seguridad de la aplicación mediante pruebas rigurosas.</p><ul><li>Pruebas Funcionales (Caja Negra) y Pruebas Estructurales (Caja Blanca).</li><li>Pruebas de rendimiento, estrés y concurrencia de usuarios en la red.</li><li>Plan de optimización de código, consultas SQL y tiempos de respuesta.</li><li>Matriz de control de pruebas y reporte de corrección de errores críticos.</li><li><strong>Actividad:</strong> <strong>Dossier de Pruebas y Reporte de Optimización.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-plan-de-implantacion-y-despliegue-en-produccion-unidad-5" tabindex="-1">📝 Evaluación 2: Plan de Implantación y Despliegue en Producción (Unidad 5) <a class="header-anchor" href="#📝-evaluacion-2-plan-de-implantacion-y-despliegue-en-produccion-unidad-5" aria-label="Permalink to &quot;📝 Evaluación 2: Plan de Implantación y Despliegue en Producción (Unidad 5)&quot;">​</a></h3><p><strong>Objetivo:</strong> Desplegar el sistema en la infraestructura real de la organización y migrar los datos definitivos.</p><ul><li>Estrategias de implantación: directa, en paralelo o por fases.</li><li>Configuración de servidores de producción (Linux, servidor web, SGBD, certificados SSL/TLS y firewall).</li><li>Migración y depuración de datos históricos.</li><li>Pruebas de aceptación con usuarios finales (UAT) y firma de Acta de Instalación.</li><li><strong>Actividad:</strong> <strong>Informe de Despliegue y Pruebas de Aceptación Comunitaria.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-manuales-de-usuario-manual-del-sistema-y-capacitacion-unidad-7" tabindex="-1">📝 Evaluación 3: Manuales de Usuario, Manual del Sistema y Capacitación (Unidad 7) <a class="header-anchor" href="#📝-evaluacion-3-manuales-de-usuario-manual-del-sistema-y-capacitacion-unidad-7" aria-label="Permalink to &quot;📝 Evaluación 3: Manuales de Usuario, Manual del Sistema y Capacitación (Unidad 7)&quot;">​</a></h3><p><strong>Objetivo:</strong> Desarrollar la documentación técnica y formativa para garantizar la sostenibilidad y transferencia del sistema.</p><ul><li>Manual de Usuario: guía ilustrada paso a paso para operadores no técnicos.</li><li>Manual del Sistema y Administrador: arquitectura, diagrama de despliegue, scripts de respaldo/restauración de BD y licenciamiento de software libre (GPL v3).</li><li>Plan de capacitación ejecutado: talleres de entrenamiento y registros de asistencia.</li><li><strong>Actividad:</strong> <strong>Entrega de Manuales Técnicos y Registro de Capacitación.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-presentacion-y-defensa-del-proyecto-final-unidad-7" tabindex="-1">📝 Evaluación 4: Presentación y Defensa del Proyecto Final (Unidad 7) <a class="header-anchor" href="#📝-evaluacion-4-presentacion-y-defensa-del-proyecto-final-unidad-7" aria-label="Permalink to &quot;📝 Evaluación 4: Presentación y Defensa del Proyecto Final (Unidad 7)&quot;">​</a></h3><p><strong>Objetivo:</strong> Sustentar el informe final, demostrar la aplicación informática en funcionamiento y socializar los resultados.</p><ul><li>Estructura formal del Informe Final de Proyecto según la normativa UPTT.</li><li>Portafolio de Evidencias: cartas de aceptación, avales de la comunidad y control de horas de vinculación social.</li><li>Demostración integral en vivo del sistema en funcionamiento ante el jurado evaluador.</li><li>Socialización ante los representantes de la comunidad u organización beneficiaria.</li><li><strong>Actividad:</strong> <strong>Defensa Pública del Proyecto e Informe Final Empastado/Digital.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Al finalizar el Trayecto III, los estudiantes han diseñado, desarrollado, optimizado, probado e implantado un sistema de información de envergadura, demostrando sólidas competencias de ingeniería de software, arquitectura de sistemas y compromiso social con el desarrollo tecnológico de la región.</p>',19)])])}const f=i(r,[["render",c]]);export{p as __pageData,f as default};
